import { classOf } from "@tsed/core";
import { bindIntercept } from "../decorators/intercept.js";
import { ProviderBuilder } from "../domain/ProviderBuilder.js";
ProviderBuilder.add("intercept", function intercept(propertyKey, interceptorToken, options) {
    bindIntercept(classOf(this.inspect().useClass), propertyKey, interceptorToken, options);
    return this;
});
